shi đã hướng dẫn ở trên, chúng ta cũng có thể sử dụng nó như là đối số trong một hàm, hoặc là thành viên trong kiểu struct. Sau đây là ví dụ sử dụng con trỏ mảng 2 chiều trong struct: Copy#include &lt;iostream&gt;using namespace std;#include &lt;stdlib.h&gt; typedef struct str&#123; int x; int y; int *arr;&#125; number; void init_2d_array_struct(number *num) &#123; for(int i = 0; i &lt; num-&gt;y; i++) &#123; for(int j = 0; j &lt; num-&gt;x; j++) &#123; num-&gt;arr[i * num-&gt;x + j] = i * num-&gt;x + j; // Khởi tạo struct &#125; &#125;&#125; int main() &#123; // Khởi tạo và khai báo struct number num; num.x = 3; num.y = 5; // Cấp phát bộ nhớ động cho 1 mảng gồm y×x phần tử num.arr = (int*)malloc(sizeof(int) * num.x * num.y); init_2d_array_struct(&amp;num); for(int i = 0; i &lt; num.y; i++) &#123; for(int j = 0; j &lt; num.x; j++) &#123; if(j &lt; num.x - 1) &#123; cout &lt;&lt; num.arr[i * num.x + j] &lt;&lt; &quot; &quot;; &#125; else &#123; cout &lt;&lt; num.arr[i * num.x + j] &lt;&lt; endl; &#125; &#125; &#125; // Giải phóng bộ nhớ free(num.arr); return 0;&#125; Kết quả: Copy0 1 23 4 56 7 89 10 1112 13 14 Trong ví dụ trên thì chúng ta khai báo kiểu struct trong C++ với [x] là số phần tử trong một hàng và [y] là số hàng có trong struct. Con trỏ [arr] ở đây được dùng để lưu giữ địa chỉ của các dữ liệu có trong mảng 2 chiều cần tạo. Hàm init_2d_array_struct() sử dụng địa chỉ của struct đã tạo (&amp;num), và thực hiện gán các giá trị vào struct đã khai báo. Lại nữa, con trỏ arr được sử dụng để lưu giữ địa chỉ của các phần tử có trong mảng 2 chiều được tạo ra bằng cách cấp phát bộ nhớ động, thông qua hàm marloc() trong C++. Tổng kếtTrên đây Kiyoshi đã hướng dẫn bạn về cách sử dụng con trỏ mảng 2 chiều trong C++ rồi. Để nắm rõ nội dung bài học hơn, bạn hãy thực hành viết lại các ví dụ của ngày hôm nay nhé. Và hãy cùng tìm hiểu những kiến thức sâu hơn về C++ trong các bài học tiếp theo.

Hướng dẫn cách tìm số chính phương trong mảng C++. Bạn sẽ học được cách tìm và đếm số chính phương trong mảng C++, cách tìm số chính phương đầu tiên và cuối cùng có trong mảng, cách tìm số chính phương lớn nhất và nhỏ nhất trong mảng C++ cũng như thực hiện các phép toán như tính tổng hoặc tính trung bình cộng của các số chính phương trong mảng C++ sau bài học này. Tìm và đếm số chính phương trong mảng C++Để tìm và đếm số chính phương trong mảng C++, chúng ta cần phải kiểm tra từng phần tử trong mảng có phải là số chính phương hay không. Và nếu phải thì tiến hành đếm hoặc in phần tử đó là xong. Để kiểm tra một phần tử trong mảng có phải là số chính phương hay không, chúng ta sẽ dùng tới phương pháp mà Kiyoshi đã hướng dẫn trong bài:Kiểm tra số chính phương trong C++ Và chúng ta viết chương trình tìm và đếm số chính phương trong mảng C++ như sau: Copy#include &lt;iostream&gt;#include &lt;cmath&gt;using namespace std;/*Định nghĩa macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) trong mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm kiểm tra số chính phương trong C++*/int find_square_number(int n)&#123; //flag = 1 =&gt; số chính phương //flag = 0 =&gt; không phải số chính phương int flag = 0; //Tìm số bất kỳ nhỏ hơn hoặc bằng n mà bình phương bằng n int i = 0; while(i &lt;= n)&#123; if( pow( i, 2) == n ) &#123; flag = 1; break; /*Chỉ cần tìm thấy 1 số là đủ và thoát vòng lặp*/ &#125; i++; &#125; return flag;&#125;int main()&#123; int array[] = &#123;5, 4, 16, 2, 8, 7, 3, 9&#125;; int length= SIZE_OF_ARRAY(array); int count = 0; /*Tìm và đếm số chính phương trong mảng C++*/ cout &lt;&lt; &quot;Cac so chinh phuong trong mang: &quot;; for (size_t i = 0; i &lt; length; ++i) &#123; int x = array[i]; int check = find_square_number(x); if (check == 1) &#123; //Tìm thấy số chính phương cout &lt;&lt; array[i]&lt;&lt;&#x27; &#x27;; ++count; &#125; &#125; cout &lt;&lt; &quot;
So so chinh phuong trong mang: &quot;&lt;&lt; count; return 0;&#125; Kết quả phép tìm và đếm số chính phương trong mảng C++: CopyCac so chinh phuong trong mang: 4 16 9 So so chinh phuong trong mang:3 so Tính tổng các số chính phương trong mảng C++Để tính tổng các số chính phương trong mảng C++, chúng ta chỉ cần tìm các số chính phương trong mảng bằng phương pháp Kiyoshi đã trình bày, sau đó tính tổng của chúng là xong. Và chúng ta viết chương trình tính tổng các số chính phương trong mảng C++ như sau: Copy#include &lt;iostream&gt;#include &lt;cmath&gt;using namespace std;/*Định nghĩa macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) trong mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm kiểm tra số chính phương trong C++*/int find_square_number(int n)&#123; //flag = 1 =&gt; số chính phương //flag = 0 =&gt; không phải số chính phương int flag = 0; //Tìm số bất kỳ nhỏ hơn hoặc bằng n mà bình phương bằng n int i = 0; while(i &lt;= n)&#123; if( pow( i, 2) == n ) &#123; flag = 1; break; /*Chỉ cần tìm thấy 1 số là đủ và thoát vòng lặp*/ &#125; i++; &#125; return flag;&#125;int main()&#123; int array[] = &#123;5, 4, 16, 2, 8, 7, 3, 9&#125;; int length= SIZE_OF_ARRAY(array); int total = 0; /*Tìm và đếm số chính phương trong mảng C++*/ cout &lt;&lt; &quot;Cac so chinh phuong trong mang: &quot;; for (size_t i = 0; i &lt; length; ++i) &#123; int x = array[i]; int check = find_square_number(x); if (check == 1) &#123; //Tìm thấy số chính phương cout &lt;&lt; array[i]&lt;&lt;&#x27; &#x27;; total += array[i]; &#125; &#125; cout &lt;&lt; &quot;
Tong cac so chinh phuong trong mang: &quot;&lt;&lt; total; return 0;&#125; Kết quả phép tính tổng các số chính phương trong mảng C++: CopyCac so chinh phuong trong mang: 4 16 9 Tong cac so chinh phuong trong mang: 29 Tính trung bình cộng các số chính phương trong mảngĐể trung bình cộng các số chính phương trong mảng, chúng ta cần phải kết hợp cả 2 bài toán là đếm số chính phương và tính tổng các số chính phương có trong mảng mà Kiyoshi đã trình bày ở trên. Sau khi tìm được rồi, chúng ta đơn giản chia tổng cho số số chính phương là sẽ ra trung bình cộng các số chính phương trong mảng. Và chúng ta viết chương trình tính trung bình cộng các số chính phương trong mảng như sau: Copy#include &lt;iostream&gt;#include &lt;cmath&gt;using namespace std;/*Định nghĩa macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) trong mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm kiểm tra số chính phương trong C++*/int find_square_number(int n)&#123; //flag = 1 =&gt; số chính phương //flag = 0 =&gt; không phải số chính phương int flag = 0; //Tìm số bất kỳ nhỏ hơn hoặc bằng n mà bình phương bằng n int i = 0; while(i &lt;= n)&#123; if( pow( i, 2) == n ) &#123; flag = 1; break; /*Chỉ cần tìm thấy 1 số là đủ và thoát vòng lặp*/ &#125; i++; &#125; return flag;&#125;int main()&#123; int array[] = &#123;5, 4, 16, 2, 8, 7, 3, 9&#125;; int length= SIZE_OF_ARRAY(array); int total = 0, count= 0; /*Tìm và đếm số chính phương trong mảng C++*/ cout &lt;&lt; (&quot;Cac so chinh phuong trong mang: &quot;); for (size_t i = 0; i &lt; length; ++i) &#123; int x = array[i]; int check = find_square_number(x); if (check == 1) &#123; //Tìm thấy số chính phương cout &lt;&lt; array[i]&lt;&lt;&#x27; &#x27;; total += array[i]; ++count; &#125; &#125; cout &lt;&lt; &quot;
Trung binh cong cac so chinh phuong trong mang: &quot;&lt;&lt; (float)total/count; return 0;&#125; Kết quả phép tính trung bình cộng các số chính phương trong mảng: CopyCac so chinh phuong trong mang: 4 16 9 Trung binh cong cac so chinh phuong trong mang: 9.66667 Bạn hãy lưu ý cách chuyển kiểu int sang float (float)total/count) để lấy kết quả chính xác khi tìm trung bình cộng nhé. Tìm số chính phương đầu tiên và cuối cùng có trong mảngĐể tìm số chính phương đầu tiên có trong mảng, chúng ta sử dụng 1 vòng lặp để kiểm tra các phần tử từ đầu tới cuối chuỗi có phải là số chính phương hay không. Và số chính phương đầu tiên được tìm thấy chính là số chính phương đầu tiên mà chúng ta cần tìm. Một cách tương tự thì để tìm số chính phương cuối cùng có trong mảng, chúng ta cũng sử dụng 1 vòng lặp để kiểm tra các phần tử. Tuy nhiên lần này chúng ta cần kiểm tra ngược lại từ cuối chuỗi tới đầu chuỗi. Và số chính phương đầu tiên được tìm thấy chính là số chính phương cuối cùng trong mảng mà chúng ta cần tìm. Chúng ta viết chương trình tìm số chính phương đầu tiên và cuối cùng có trong mảng như sau: Copy#include &lt;iostream&gt;#include &lt;cmath&gt;using namespace std;/*Định nghĩa macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) trong mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm kiểm tra số chính phương trong C++*/int find_square_number(int n)&#123; //flag = 1 =&gt; số chính phương //flag = 0 =&gt; không phải số chính phương int flag = 0; //Tìm số bất kỳ nhỏ hơn hoặc bằng n mà bình phương bằng n int i = 0; while(i &lt;= n)&#123; if( pow( i, 2) == n ) &#123; flag = 1; break; /*Chỉ cần tìm thấy 1 số là đủ và thoát vòng lặp*/ &#125; i++; &#125; return flag;&#125;int main()&#123; int array[] = &#123;5, 4, 16, 2, 8, 7, 3, 9&#125;; int length= SIZE_OF_ARRAY(array); /*tìm số chính phương đầu tiên có trong mảng*/ for (size_t i = 0; i &lt; length; ++i) &#123; int x = array[i]; int check = find_square_number(x); if (check == 1) &#123; //Tìm thấy số chính phương cout &lt;&lt; &quot;So chinh phuong dau tien: &quot;&lt;&lt; array[i]&lt;&lt;endl; break; &#125; &#125; /*tìm số chính phương cuối cùng có trong mảng*/ for (size_t i = length-1; i &gt;= 0; --i) &#123; int x = array[i]; int check = find_square_number(x); if (check == 1) &#123; //Tìm thấy số chính phương cout &lt;&lt; &quot;So chinh phuong cuoi cung: &quot;&lt;&lt; array[i]; break; &#125; &#125; return 0;&#125; Kết quả phép tìm số chính phương đầu tiên và cuối cùng có trong mảng: CopySo chinh phuong dau tien: 4 So chinh phuong cuoi cung: 9 Tìm số chính phương lớn nhất và nhỏ nhất trong mảng C++Để số chính phương lớn nhất và nhỏ nhất trong mảng C++, đầu tiên chúng ta cần phải sắp xếp các phần tử trong mảng đó theo thứ tự giảm dần. Sau khi sắp xếp, số chính phương lớn nhất trong mảng chính là số chính phương đầu tiên có trong mảng. Và ngược lại thì số chính phương nhỏ nhất trong mảng chính là số chính phương cuối cùng có trong mảng. Về sắp xếp mảng trong C++ thì chúng ta sẽ dùng tới phương pháp mà Kiyoshi đã hướng dẫn trong bài: Sắp xếp mảng trong C++ Và chúng ta viết chương trình tìm số chính phương đầu tiên và cuối cùng có trong mảng như sau: Copy#include &lt;iostream&gt;#include &lt;cmath&gt;#include &lt;cstdlib&gt;using namespace std;/*Định nghĩa macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) trong mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm so sánh giảm dần sử dụng trong hàm qsort*/int compareIntDesc(const void* a, const void* b)&#123; int aNum = *(int*)a; int bNum = *(int*)b; return bNum - aNum;&#125;/*Tạo hàm kiểm tra số chính phương trong C++*/int find_square_number(int n)&#123; //flag = 1 =&gt; số chính phương //flag = 0 =&gt; không phải số chính phương int flag = 0; //Tìm số bất kỳ nhỏ hơn hoặc bằng n mà bình phương bằng n int i = 0; while(i &lt;= n)&#123; if( pow( i, 2) == n ) &#123; flag = 1; break; /*Chỉ cần tìm thấy 1 số là đủ và thoát vòng lặp*/ &#125; i++; &#125; return flag;&#125;int main()&#123; int array[] = &#123;5, 4, 16, 2, 8, 7, 3, 9&#125;; int length= SIZE_OF_ARRAY(array); /*Sử dụng hàm qsort để sắp xếp mảng giảm dần*/ qsort(array, length, sizeof(int), compareIntDesc); /*Tìm số chính phương đầu tiên có trong mảng Cũng chính là số chính phương lớn nhất trong mảng */ for (size_t i = 0; i &lt; length; ++i) &#123; int x = array[i]; int check = find_square_number(x); if (check == 1) &#123; //Tìm thấy số chính phương cout &lt;&lt; &quot;So chinh phuong lon nhat: &quot;&lt;&lt; array[i] &lt;&lt;endl; break; &#125; &#125; /*Tìm số chính phương cuối cùng có trong mảng Cũng chính là số chính phương nhỏ nhất trong mảng */ for (size_t i = length-1; i &gt;= 0; --i) &#123; int x = array[i]; int check = find_square_number(x); if (check == 1) &#123; //Tìm thấy số chính phương cout &lt;&lt; &quot;So chinh phuong nho nhat: &quot;&lt;&lt; array[i]; break; &#125; &#125; return 0;&#125; Kết quả phép số chính phương lớn nhất và nhỏ nhất trong mảng C++: CopySo chinh phuong lon nhat: 16 So chinh phuong nho nhat: 4 Tổng kếtTrên đây Kiyoshi đã hướng dẫn bạn cách tìm số chính phương trong mảng C++ rồi. Để nắm rõ nội dung bài học hơn, bạn hãy thực hành viết lại các ví dụ của ngày hôm nay nhé. Và hãy cùng tìm hiểu những kiến thức sâu hơn về C++ trong các bài học tiếp theo.

