Hướng dẫn cách liệt kê các phần tử xuất hiện trong mảng C. Bạn sẽ học được cách liệt kê các phần tử xuất hiện một lần trong mảng C, cũng như cách liệt kê các phần tử xuất hiện nhiều hơn 1 lần sau bài học này. Liệt kê các phần tử duy nhất trong mảng CĐể liệt kê các phần tử duy nhất trong mảng C, chúng ta cần xóa đi tất cả các phần tử trùng trong mảng ban đầu. Khi đó kết quả còn lại chính là các phần tử duy nhất có trong mảng đó. Để xóa phần tử trùng trong mảng C, chúng ta sẽ sử dụng tới một trong 2 cách mà Kiyoshi đã hướng dẫn trong bài: Xem thêm: Xóa phần tử trùng trong mảng C Và dưới đây là cách liệt kê các phần tử duy nhất trong mảng C thông qua việc xoá phần tử trùng trong một mảng đã được sắp xếp như sau: Copy#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;/*Tạo macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) của mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm in phần tử trong mảng*/void show_array(int array[], int length)&#123; for(short i = 0; i &lt; length; i++) printf(&quot;%d &quot;, array[i]); printf(&quot;
&quot;);&#125;/*Tạo hàm so sánh tăng dần sử dụng trong hàm qsort*/int compareIntAsc(const void* a, const void* b)&#123; int aNum = *(int*)a; int bNum = *(int*)b; return aNum - bNum;&#125;/*Tạo hàm xoá phần tử trùng lặp trong mảng đã sắp xếp*/void array_unique(int* array, size_t size)&#123; size_t end = 0; for (size_t i = 1; i &lt; size; ++i) &#123; if (array[i] != array[end]) &#123; ++end; array[end] = array[i]; &#125; &#125; //Liệt kê các phần tử xuất hiện một lần trong mảng C show_array(array, end+1);&#125;int main(void)&#123; int array1[] = &#123; 7, 2, 6, 7, 4, 9, 8 &#125;; int array2[] = &#123; 7, 2, 6, 7, 7 &#125;; int array3[] = &#123; 7, 7, 7 &#125;; // Sắp xếp các mảng theo thứ tự tăng dần qsort(array1, SIZE_OF_ARRAY(array1), sizeof(int), compareIntAsc); qsort(array2, SIZE_OF_ARRAY(array2), sizeof(int), compareIntAsc); qsort(array3, SIZE_OF_ARRAY(array3), sizeof(int), compareIntAsc); //Xoá phần tử trùng nhau và liệt kê các phần tử duy nhất array_unique(array1, SIZE_OF_ARRAY(array1)); array_unique(array2, SIZE_OF_ARRAY(array2)); array_unique(array3, SIZE_OF_ARRAY(array3)); return 0;&#125; Kết quả phép liệt kê các phần tử duy nhất trong mảng Cnhư sau: Copy2 4 6 7 8 9 2 6 7 7 Liệt kê các phần tử xuất hiện một lần trong mảng CĐể liệt kê các phần tử xuất hiện một lần trong mảng C, chúng ta đơn giản kiểm tra từng phần tử xem có phần tử nào trùng với nó trong mảng ban đầu hay không. Chúng ta có thể sử dụng vòng lặp để lấy và kiểm tra từng phần tử và liệt kê các phần tử xuất hiện một lần trong mảng C như sau đây: Copy#include &lt;stdio.h&gt;/*Tạo macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) của mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm liệt kê các phần tử xuất hiện một lần trong mảng C*/void array_unique(int* array, size_t size)&#123; for (size_t i = 0; i &lt; size; ++i) &#123; size_t count = 0; for (size_t j = 0; j &lt; size; ++j) &#123; if (array[i] == array[j] &amp;i!=j) &#123; //Tìm thấy phần tử trùng nhau thì tăng biến đếm count += 1; &#125; &#125; /*Nếu count vẫn bằng 0 thì phần tử đang kiểm tra chỉ xuất hiện 1 lần duy nhất trong mảng*/ if(count==0) printf(&quot;%d &quot;,array[i]); &#125; printf(&quot;
&quot;);&#125;int main(void)&#123; int array1[] = &#123; 7, 2, 6, 7, 4, 9, 8 &#125;; int array2[] = &#123; 7, 2, 6, 7, 7 &#125;; int array3[] = &#123; 7, 7, 7 &#125;; //Xoá phần tử trùng nhau và liệt kê các phần tử xuất hiện một lần trong kết quả array_unique(array1, SIZE_OF_ARRAY(array1)); array_unique(array2, SIZE_OF_ARRAY(array2)); array_unique(array3, SIZE_OF_ARRAY(array3)); return 0;&#125; Kết quả phép liệt kê các phần tử xuất hiện một lần trong mảng Cnhư sau: Copy2 6 4 9 8 2 6 Liệt kê các phần tử xuất hiện nhiều hơn 1 lần trong mảng CCác phần tử xuất hiện nhiều hơn 1 lần trong mảng C chính là các phần tử trùng nhau. Để liệt kê các xuất hiện nhiều hơn 1 lần này, chúng ta sẽ dùng tới hàm tự tạo mà Kiyoshi đã hướng dẫn trong bài: Xem thêm: Kiểm tra và lấy phần tử trùng trong mảng C Và chúng ta viết hàm liệt kê các phần tử xuất hiện nhiều hơn 1 lần mảng C trong chương trình như sau: Copy#include &lt;stdio.h&gt;/*Tạo macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) của mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm in phần tử trong mảng*/void show_array(int array[], int length)&#123; for(short i = 0; i &lt; length; i++) printf(&quot;%d &quot;, array[i]); printf(&quot;
