Hướng dẫn cách kiểm tra và lấy phần tử trùng trong mảng C. Bạn sẽ học được 2 cách căn bản để kiểm tra phần tử trùng trong mảng C cũng như ứng dụng chúng để lấy phần tử trùng nhau trong mảng C sau bài học này. Chúng ta có 2 phương pháp kiểm tra phần tử trùng trong mảng C như sau: Kiểm tra phần tử trùng trong mảng C bằng cách so sánh từng phần tử Kiểm tra phần tử trùng trong mảng C bằng cách sắp xếp mảng Và ứng dụng một trong 2 phương pháp kiểm tra ở trên, chúng ta cũng có thể tiến hành lấy phần tử trùng trong mảng C. Kiểm tra phần tử trùng trong mảng C bằng cách so sánh từng phần tửĐể kiểm tra phần tử trùng trong mảng C, chúng ta có thể lấy lần lượt từng phần tử và so sánh xem có phần tử nào giống nó trong chuỗi ban đầu hay không. Nếu tồn tại dù chỉ một cặp phần tử giống nhau, điều đó có nghĩa là tồn tại phần tử trùng nhau trong mảng ban đầu, và ngược lại nếu tất cả đều khác nhau thì không tồn tại phần tử trùng nhau trong mảng ban đầu. Để làm được điều đó, chúng ta cần dùng tới một vòng lặp lồng để lấy và kiểm tra từng phần tử trong mảng ban đầu. Và chúng ta viết hàm kiểm tra phần tử trùng trong mảng C trong chương trình như sau: Copy#include &lt;stdio.h&gt;/*Tạo macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) của mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm kiểm tra phần tử trùng trong mảng C*/int array_is_unique(const int* array, size_t size)&#123; //flag = 1 =&gt; tồn tại phần tử trùng nhau //flag = 0 =&gt; không tồn tại phần tử trùng nhau int flag = 0; for (size_t i = 0; i &lt; size - 1; ++i) &#123; for (size_t j = i + 1; j &lt; size; ++j) &#123; if (array[i] == array[j]) &#123; flag = 1; break; &#125; &#125; &#125; return flag;&#125;int main(void)&#123; //Khởi tạo mảng cần kiểm tra phần tử trùng nhau int array1[] = &#123;1,2,3,3,2,5&#125;; //Mảng chứa phần tử trùng nhau int array2[] = &#123;1,2,3,4,5,6,7&#125;; //Mảng không chứa phần tử trùng nhau //Kiểm tra phần tử trùng nhau int check1 = array_is_unique(array1,SIZE_OF_ARRAY(array1)); if (check1 == 1) printf(&quot;ton tai phan tu trung nhau&quot;); else printf(&quot;khong ton tai phan tu trung nhau&quot;); printf(&quot;
&quot;); //Kiểm tra phần tử trùng nhau int check2 = array_is_unique(array2,SIZE_OF_ARRAY(array2)); if (check2 == 1) printf(&quot;ton tai phan tu trung nhau&quot;); else printf(&quot;khong ton tai phan tu trung nhau&quot;); return 0;&#125; Kết quả phép kiểm tra phần tử trùng trong mảng C như sau: Copyton tai phan tu trung nhaukhong ton tai phan tu trung nhau Kiểm tra phần tử trùng trong mảng C bằng cách sắp xếp mảngNgoài cách so sánh từng phần tử trong mảng bằng vòng lặp lồng như trên, chúng ta cũng có thể kiểm tra phần tử trùng trong mảng C bằng cách sắp xếp mảng. Ý tưởng ở đây là, sau khi sắp xếp mảng, thì các phần tử trùng nhau (nếu có) sẽ được xếp nằm cạnh nhau, do đó nếu chúng ta kiểm tra trong mảng sau khi sắp xếp có tồn tại phần tử nào giống với phần tử đằng sau nó, thì điều đó chứng tỏ mảng ban đầu có tồn tại phần tử trùng nhau. Để sắp xếp mảng trong C, chúng ta sẽ sử dụng tới hàm qsort() mà Kiyoshi đã hướng dẫn trong bài: Xem thêm: Sắp xếp mảng trong C Và chúng ta viết hàm kiểm tra phần tử trùng trong mảng C trong chương trình như sau: Copy#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;/*Tạo macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) của mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm so sánh tăng dần sử dụng trong hàm qsort*/int compareIntAsc(const void* a, const void* b)&#123; int aNum = *(int*)a; int bNum = *(int*)b; return aNum - bNum;&#125;/*Tạo hàm kiểm tra phần tử trùng trong mảng C*/int array_is_unique(const int* array, size_t size)&#123; //flag = 1 =&gt; tồn tại phần tử trùng nhau //flag = 0 =&gt; không tồn tại phần tử trùng nhau int flag = 0; for (size_t i = 0; i &lt; size - 1; ++i) &#123; if (array[i] == array[i + 1]) &#123; flag = 1; break; &#125; &#125; return flag;&#125;int main(void)&#123; //Khởi tạo mảng cần kiểm tra phần tử trùng nhau int array1[] = &#123;1,2,3,3,2,5&#125;; //Mảng chứa phần tử trùng nhau int array2[] = &#123;1,2,3,4,5,6,7&#125;; //Mảng không chứa phần tử trùng nhau //Sắp xếp mảng theo thứ tự tăng dần qsort(array1, SIZE_OF_ARRAY(array1), sizeof(int), compareIntAsc); qsort(array2, SIZE_OF_ARRAY(array2), sizeof(int), compareIntAsc); //Kiểm tra phần tử trùng nhau int check1 = array_is_unique(array1,SIZE_OF_ARRAY(array1)); if (check1 == 1) printf(&quot;ton tai phan tu trung nhau&quot;); else printf(&quot;khong ton tai phan tu trung nhau&quot;); printf(&quot;
&quot;); int check2 = array_is_unique(array2,SIZE_OF_ARRAY(array2)); if (check2 == 1) printf(&quot;ton tai phan tu trung nhau&quot;); else printf(&quot;khong ton tai phan tu trung nhau&quot;); return 0;&#125; Kết quả phép kiểm tra phần tử trùng trong mảng C như sau: Copyton tai phan tu trung nhaukhong ton tai phan tu trung nhau Lấy phần tử trùng trong mảng CBằng cách sử dụng một trong hai phương pháp ở trên, chúng ta có thể biến tấu chương trình để có thể lấy phần tử trùng trong mảng C. Ví dụ, chúng ta sử dụng cách 1 và thay đổi chút xíu hàm kiểm tra phần tử trùng nhau để tạo ra hàm lấy phần tử trùng trong mảng C như sau: Copy#include &lt;stdio.h&gt;/*Tạo macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) của mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm in phần tử trong mảng*/void show_array(int array[], int length)&#123; for(short i = 0; i &lt; length; i++) printf(&quot;%d &quot;, array[i]); printf(&quot;
&quot;);&#125;/*Thay đổi hàm kiểm tra phần tử trùng nhau ở phương pháp một*//*Và tạo hàm lấy phần tử trùng trong mảng C*/void take_duplicate_element(const int* array, size_t size)&#123; int result[100], count=0; for (size_t i = 0; i &lt; size - 1; ++i) &#123; for (size_t j = i + 1; j &lt; size; ++j) &#123; if (array[i] == array[j]) &#123; result[count]=array[i]; ++ count; &#125; &#125; &#125; show_array(result, count);&#125;int main(void)&#123; int array1[] = &#123;1,2,3,3,2,5&#125;; int array2[] = &#123;1,1,2,3,2,5,5,8,9,6&#125;; //Lấy phần tử trùng nhau take_duplicate_element(array1,SIZE_OF_ARRAY(array1)); take_duplicate_element(array2,SIZE_OF_ARRAY(array2)); return 0;&#125; Kết quả phép lấy phần tử trùng trong mảng C như sau: Copy2 3 1 2 5 Tổng kếtTrên đây Kiyoshi đã hướng dẫn bạn cách kiểm tra phần tử trùng trong mảng C cũng như cách lấy phần tử trùng nhau trong mảng C rồi. Để nắm rõ nội dung bài học hơn, bạn hãy thực hành viết lại các ví dụ của ngày hôm nay nhé. Và hãy cùng tìm hiểu những kiến thức sâu hơn về C trong các bài học tiếp theo.

Hướng dẫn cách tìm số chính phương trong mảng C. Bạn sẽ học được cách tìm và đếm số chính phương trong mảng C, cách tìm số chính phương đầu tiên và cuối cùng có trong mảng, cách tìm số chính phương lớn nhất và nhỏ nhất trong mảng C cũng như thực hiện các phép toán như tính tổng hoặc tính trung bình cộng của các số chính phương trong mảng C sau bài học này. Tìm và đếm số chính phương trong mảng CĐể tìm và đếm số chính phương trong mảng C, chúng ta cần phải kiểm tra từng phần tử trong mảng có phải là số chính phương hay không. Và nếu phải thì tiến hành đếm hoặc in phần tử đó là xong. Để kiểm tra một phần tử trong mảng có phải là số chính phương hay không, chúng ta sẽ dùng tới phương pháp mà Kiyoshi đã hướng dẫn trong bài:Kiểm tra số chính phương trong C Và chúng ta viết chương trình tìm và đếm số chính phương trong mảng C như sau: Copy#include &lt;stdio.h&gt;#include &lt;math.h&gt;/*Định nghĩa macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) trong mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm kiểm tra số chính phương trong C*/int find_square_number(int n)&#123; //flag = 1 =&gt; số chính phương //flag = 0 =&gt; không phải số chính phương int flag = 0; //Tìm số bất kỳ nhỏ hơn hoặc bằng n mà bình phương bằng n int i = 0; while(i &lt;= n)&#123; if( pow( i, 2) == n ) &#123; flag = 1; break; /*Chỉ cần tìm thấy 1 số là đủ và thoát vòng lặp*/ &#125; i++; &#125; return flag;&#125;int main(void)&#123; int array[] = &#123;5, 4, 16, 2, 8, 7, 3, 9&#125;; int length= SIZE_OF_ARRAY(array); int count = 0; /*Tìm và đếm số chính phương trong mảng C*/ printf(&quot;Cac so chinh phuong trong mang: &quot;); for (size_t i = 0; i &lt; length; ++i) &#123; int x = array[i]; int check = find_square_number(x); if (check == 1) &#123; //Tìm thấy số chính phương printf(&quot;%d &quot;, array[i]); ++count; &#125; &#125; printf(&quot;
So so chinh phuong trong mang:%d so&quot;, count); return 0;&#125; Kết quả phép tìm và đếm số chính phương trong mảng C: CopyCac so chinh phuong trong mang: 4 16 9 So so chinh phuong trong mang:3 so Tính tổng các số chính phương trong mảng CĐể tính tổng các số chính phương trong mảng C, chúng ta chỉ cần tìm các số chính phương trong mảng bằng phương pháp Kiyoshi đã trình bày, sau đó tính tổng của chúng là xong. Và chúng ta viết chương trình tính tổng các số chính phương trong mảng C như sau: Copy#include &lt;stdio.h&gt;#include &lt;math.h&gt;/*Định nghĩa macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) trong mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm kiểm tra số chính phương trong C*/int find_square_number(int n)&#123; //flag = 1 =&gt; số chính phương //flag = 0 =&gt; không phải số chính phương int flag = 0; //Tìm số bất kỳ nhỏ hơn hoặc bằng n mà bình phương bằng n int i = 0; while(i &lt;= n)&#123; if( pow( i, 2) == n ) &#123; flag = 1; break; /*Chỉ cần tìm thấy 1 số là đủ và thoát vòng lặp*/ &#125; i++; &#125; return flag;&#125;int main(void)&#123; int array[] = &#123;5, 4, 16, 2, 8, 7, 3, 9&#125;; int length= SIZE_OF_ARRAY(array); int total = 0; /*Tìm và đếm số chính phương trong mảng C*/ printf(&quot;Cac so chinh phuong trong mang: &quot;); for (size_t i = 0; i &lt; length; ++i) &#123; int x = array[i]; int check = find_square_number(x); if (check == 1) &#123; //Tìm thấy số chính phương printf(&quot;%d &quot;, array[i]); total += array[i]; &#125; &#125; printf(&quot;
