&quot;, array[i]); break; &#125; &#125; /*tìm số chính phương cuối cùng có trong mảng*/ for (size_t i = length-1; i &gt;= 0; --i) &#123; int x = array[i]; int check = find_square_number(x); if (check == 1) &#123; //Tìm thấy số chính phương printf(&quot;So chinh phuong cuoi cung: %d &quot;, array[i]); break; &#125; &#125; return 0;&#125; Kết quả phép tìm số chính phương đầu tiên và cuối cùng có trong mảng: CopySo chinh phuong dau tien: 4 So chinh phuong cuoi cung: 9 Tìm số chính phương lớn nhất và nhỏ nhất trong mảng CĐể số chính phương lớn nhất và nhỏ nhất trong mảng C, đầu tiên chúng ta cần phải sắp xếp các phần tử trong mảng đó theo thứ tự giảm dần. Sau khi sắp xếp, số chính phương lớn nhất trong mảng chính là số chính phương đầu tiên có trong mảng. Và ngược lại thì số chính phương nhỏ nhất trong mảng chính là số chính phương cuối cùng có trong mảng. Về sắp xếp mảng trong C thì chúng ta sẽ dùng tới phương pháp mà Kiyoshi đã hướng dẫn trong bài: Sắp xếp mảng trong C Và chúng ta viết chương trình tìm số chính phương đầu tiên và cuối cùng có trong mảng như sau: Copy#include &lt;stdio.h&gt;#include &lt;math.h&gt;#include &lt;stdlib.h&gt;/*Định nghĩa macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) trong mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm so sánh giảm dần sử dụng trong hàm qsort*/int compareIntDesc(const void* a, const void* b)&#123; int aNum = *(int*)a; int bNum = *(int*)b; return bNum - aNum;&#125;/*Tạo hàm kiểm tra số chính phương trong C*/int find_square_number(int n)&#123; //flag = 1 =&gt; số chính phương //flag = 0 =&gt; không phải số chính phương int flag = 0; //Tìm số bất kỳ nhỏ hơn hoặc bằng n mà bình phương bằng n int i = 0; while(i &lt;= n)&#123; if( pow( i, 2) == n ) &#123; flag = 1; break; /*Chỉ cần tìm thấy 1 số là đủ và thoát vòng lặp*/ &#125; i++; &#125; return flag;&#125;int main(void)&#123; int array[] = &#123;5, 4, 16, 2, 8, 7, 3, 9&#125;; int length= SIZE_OF_ARRAY(array); /*Sử dụng hàm qsort để sắp xế