&quot;, array[i]); break; &#125; &#125; /*Tìm số chính phương cuối cùng có trong mảng Cũng chính là số chính phương nhỏ nhất trong mảng */ for (size_t i = length-1; i &gt;= 0; --i) &#123; int x = array[i]; int check = find_square_number(x); if (check == 1) &#123; //Tìm thấy số chính phương printf(&quot;So chinh phuong nho nhat: %d &quot;, array[i]); break; &#125; &#125; return 0;&#125; Kết quả phép số chính phương lớn nhất và nhỏ nhất trong mảng C: CopySo chinh phuong lon nhat: 16 So chinh phuong nho nhat: 4 Tổng kếtTrên đây Kiyoshi đã hướng dẫn bạn cách tìm số chính phương trong mảng C rồi. Để nắm rõ nội dung bài học hơn, bạn hãy thực hành viết lại các ví dụ của ngày hôm nay nhé. Và hãy cùng tìm hiểu những kiến thức sâu hơn về C trong các bài học tiếp theo.

Hướng dẫn cách tách mảng âm dương trong C. Bạn sẽ học được cách viết một chương trình C cơ bản để tách các số âm/dương ra 1 mảng khác từ mảng cho trước sau bài học này. Tách mảng âm dương trong CĐể tách các số âm/dương ra 1 mảng khác từ mảng cho trước, chúng ta đơn giản chuẩn bị sẵn 2 mảng chứa kết quả phép tách, một mảng để chứa các số âm và một mảng để chứa các số dương được tách ra từ mảng ban đầu. Và để kiểm tra một số trong mảng là số âm hay số dương, chúng ta đơn giản so sánh số đó với 0, hoặc là sử dụng tới hàm mà Kiyoshi đã giới thiệu trong bài dưới đây: Xem thêm: Kiểm tra số âm số dương trong C Và chúng ta viết chương trình tách các số âm/dương ra 1 mảng khác từ mảng cho trước bằng C như sau: Copy#include &lt;stdio.h&gt;/*Tạo macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) của mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm in phần tử trong mảng*/void show_array(int array[], int length)&#123; for(short i = 0; i &lt; length; i++) printf(&quot;%d &quot;, array[i]); printf(&quot;
&quot;);&#125;int main(void)&#123; //Khai báo 2 mảng chứa kết quả int negative_array[100], positive_array[100]; //Khởi tạo mảng cần tách ra các số âm dương int array[] = &#123;-5, 4, 0 , 1, -2 ,9 , 7,-8&#125;; //Sử dụng macro ở trên để lấy độ dài mảng int length = SIZE_OF_ARRAY(array); int negative_count = 0, positive_count = 0; for (int i = 0; i &lt; length; i++)&#123; //Kiểm tra phần tử là số âm hay dương //Và gán số tìm thấy vào các mảng âm dương tương ứng //Cũng như tăng dần số phần tử trong mảng kết quả if (array[i] &lt; 0) &#123; negative_array[negative_count]=array[i]; ++ negative_count; &#125; else if (array[i] &gt; 0) &#123; positive_array[positive_count]=array[i]; ++ positive_count; &#125; &#125; //In ra mảng âm dương đã tách ra show_array(negative_array, negative_count); show_array(positive_array, positive_count); return 0;&#125; Kết quả của phép tách mảng âm dương trong C như sau: Copy-5 -2 -8 4 1 9 7 Tách số dương trong mảng CMột cách tương tự thì chúng ta có thể tiến hành tách số dương trong mảng C, và bài toán này đơn giản hơn nhiều so với bài toán ở trên, bởi vì chúng ta chỉ cần chuẩn bị một mảng chứa số dương được tách từ mảng ban đầu mà thôi. Chúng ta viết chương trình như sau: Copy#include &lt;stdio.h&gt;/*Tạo macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) của mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm in phần tử trong mảng*/void show_array(int array[], int length)&#123; for(short i = 0; i &lt; length; i++) printf(&quot;%d &quot;, array[i]); printf(&quot;
