&quot;);&#125;/*Viết hàm kiểm tra số nguyên trong C*/int check_real_integer_number(float n)&#123; //flag = 1 =&gt; là số nguyên //flag = 0 =&gt; không phải là số nguyên int flag = 1; if (ceil(n) != floor(n)) flag = 0; return flag;&#125;int main(void)&#123; int positive_array[100]; float array[] = &#123;-5, 4, 0 , 1.2, -2.7 ,9 , 7.3,-8&#125;; int length = SIZE_OF_ARRAY(array); int positive_count = 0; for (int i = 0; i &lt; length; i++)&#123; float n = array[i]; //Kiểm tra số đã cho có thoả mãn là số dương, và là số nguyên hay không //Và gán số tìm thấy vào các mảng âm dương tương ứng //Cũng như tăng dần số phần tử trong mảng kết quả if (n &gt; 0 &amp;&amp; check_real_integer_number(n) == 1) &#123; positive_array[positive_count]=array[i]; ++ positive_count; &#125; &#125; show_array(positive_array, positive_count); return 0;&#125; Kết quả : Copy4 9 Tổng kếtTrên đây Kiyoshi đã hướng dẫn bạn cách tách mảng âm dương trong C rồi. Để nắm rõ nội dung bài học hơn, bạn hãy thực hành viết lại các ví dụ của ngày hôm nay nhé. Và hãy cùng tìm hiểu những kiến thức sâu hơn về C trong các bài học tiếp theo.

Hướng dẫn cách sắp xếp mảng trong C. Bạn sẽ học được cách sắp xếp phần tử trong mảng C bằng hàm qsort() trong thư viện chuẩn, cũng như cách tự tạo hàm sắp xếp mảng trong C sau bài học này. Chúng ta có 3 phương pháp để sắp xếp mảng trong C như sau: Sắp xếp phần tử trong mảng C theo thứ tự tăng dần bằng hàm qsort Sắp xếp phần tử trong mảng C theo thứ tự giảm dần dần bằng hàm qsort Sắp xếp mảng trong C bằng hàm tự tạo Sắp xếp mảng tăng dần trong C bằng hàm qsortHàm qsort trong C là một hàm có sẵn trong header file stdlib.h, giúp chúng ta sắp xếp mảng trong C. Cú pháp sử dụng hàm qsort() trong C như sau: qsort(array, length, size, compare_fuct); Trong đó: array là mảng cần so sánh length là độ dài (số phần tử) của mảng đó. Xem thêm: Độ dài mảng trong C. size là kích thước một phần tử trong mảng. Ví dụ như kiểu int là 4 byte, char là 1 byte chẳng hạn. Xem thêm: Kiểu dữ liệu trong C. compare_fuct là hàm so sánh để quyết định thứ tự sắp xếp Để quyết định thứ tự sắp xếp mảng bằng hàm qsort(), chúng ta cần sử dụng tới một hàm trung gian là hàm so sánh compare_fuct giúp tìm ra quan hệ lớn nhỏ giữa hai phần tử. Trong trường hợp sắp xếp mảng tăng dần trong C thì chúng ta sẽ định nghĩa hàm so sánh này như sau: Copyint compareIntAsc(const void* a, const void* b)&#123; int aNum = *(int*)a; int bNum = *(int*)b; return aNum - bNum;&#125; Và chúng ta sử dụng hàm qsort để viết chương trình sắp xếp phần tử trong mảng C theo thứ tự tăng dần như sau: Copy#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;/*Định nghĩa macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) trong mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm in phần tử trong mảng*/void show_array(int array[], int length)&#123; for(short i = 0; i &lt; length; i++) printf(&quot;%d &quot;, array[i]); printf(&quot;
&quot;);&#125;/*Tạo hàm so sánh tăng dần sử dụng trong hàm qsort*/int compareIntAsc(const void* a, const void* b)&#123; int aNum = *(int*)a; int bNum = *(int*)b; return aNum - bNum;&#125;int main(void)&#123; int array1[] = &#123;5, 4, 7, 2, 8, 7, 3&#125;; int array2[] = &#123;99, 4, 5, 2, 80, 7, 3&#125;; /*Sử dụng hàm qsort để sắp xếp mảng tăng dần*/ qsort(array1, SIZE_OF_ARRAY(array1), sizeof(int), compareIntAsc); qsort(array2, SIZE_OF_ARRAY(array2), sizeof(int), compareIntAsc); /*Xem kết quả sắp xếp mảng*/ show_array(array1, SIZE_OF_ARRAY(array1)); show_array(array2, SIZE_OF_ARRAY(array2)); return 0;&#125; Kết quả của phép sắp xếp mảng tăng dần trong C như dưới đây. Bạn hãy thử chạy chương trình và kiểm tra nhé. Copy2 3 4 5 7 7 8 2 3 4 5 7 80 99 Sắp xếp mảng giảm dần trong C bằng hàm qsortNhư ở phần trên Kiyoshi đã giải thích, thì việc sắp xếp tăng dần hay giảm dần mảng trong C bằng hàm qsort() sẽ phụ thuộc vào hàm so sánh sử dụng trong hàm này. Do đó, để sắp xếp phần tử trong mảng C theo thứ tự giảm dần dần bằng hàm qsort, chúng ta đơn giản chỉ cần thay đổi hàm so sánh như dưới đây là xong: Copyint compareIntDesc(const void* a, const void* b)&#123; int aNum = *(int*)a; int bNum = *(int*)b; return bNum - aNum;&#125; Sự khác biệt giữa 2 hàm so sánh này là ở giá trị mà nó trả về. Với hàm compareIntAsc() ở sắp xếp tăng dần thì chúng ta trả về return aNum - bNum, và với hàm compareIntDesc() ở sắp xếp giảm dần thì chúng ta trả về giá trị ngược lại là return bNum - aNum. Và chúng ta sử dụng hàm qsort để viết chương trình sắp xếp phần tử trong mảng C theo thứ tự giảm dần như sau: Copy#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;/*Định nghĩa macro SIZE_OF_ARRAY để lấy độ dài (số phần tử) trong mảng chỉ định*/#define SIZE_OF_ARRAY(array) (sizeof(array)/sizeof(array[0]))/*Tạo hàm in phần tử trong mảng*/void show_array(int array[], int length)&#123; for(short i = 0; i &lt; length; i++) printf(&quot;%d &quot;, array[i]); printf(&quot;
&quot;);&#125;/*Tạo hàm so sánh giảm dần sử dụng trong hàm qsort*/int compareIntDesc(const void* a, const void* b)&#123; int aNum = *(int*)a; int bNum = *(int*)b; return bNum - aNum;&#125;int main(void)&#123; int array1[] = &#123;5, 4, 7, 2, 8, 7, 3&#125;; int array2[] = &#123;99, 4, 5, 2, 80, 7, 3&#125;; /*Sử dụng hàm qsort để sắp xếp mảng giảm dần*/ qsort(array1, SIZE_OF_ARRAY(array1), sizeof(int), compareIntDesc); qsort(array2, SIZE_OF_ARRAY(array2), sizeof(int), compareIntDesc); /*Xem kết quả sắp xếp mảng*/ show_array(array1, SIZE_OF_ARRAY(array1)); show_array(array2, SIZE_OF_ARRAY(array2)); return 0;&#125; Kết quả của phép sắp xếp mảng giảm dần trong C như dưới đây. Bạn hãy thử chạy chương trình và kiểm tra nhé. Copy8 7 7 5 4 3 2 99 80 7 5 4 3 2 Sắp xếp mảng trong C bằng hàm tự tạoChúng ta nên sử dụng hàm qsort() ở trên trong các dự án thực tế khi cần sắp xếp mảng trong C. Tuy nhiên nếu bạn muốn luyện tập viết code C, cũng như muốn hiểu rõ hơn về cách sắp xếp trong C như thế nào, thì hãy thử tự tạo các hàm sắp xếp mảng tăng dần và giảm dần trong C ở phần dưới đây. Logic sắp xếp mảngVí dụ chúng ta có mảng int như sau: Copyint array[] = &#123;4, 1, 0, 2, 3&#125;; Để sắp xếp mảng này tăng dần trong C, chúng ta sử dụng ý tưởng rất đơn giản. Chúng ta xét số đầu tiên của mảng và so sánh lần lượt với các số còn lại từ vị trí số đó tới cuối mảng. Nếu tìm thấy số đầu tiên nhỏ hơn số đang xét thì sẽ hoán đổi vị trí của 2 số này với nhau, rồi tiếp tục lặp cho tới khi không còn số nào nhỏ hơn số đang xét nữa, thì chuyển sang xét ở số thứ 2 trong mảng. Cứ như thế cho tới khi tất cả các số đều được xét. Với mảng ở trên thì chúng ta sẽ hoán đổi lần lượt như sau: So sánh số đầu tiên là số 4 lần lượt với các số còn lại. Số 1 là số đầu tiên nhỏ hơn 4 nên hoán đổi vị trí 4 với 1. Lúc này, 1 trở thành số đầu tiên trong mảng. So sánh 1 lần lượt với các số còn lại. Số 0 là số đầu tiên nhỏ hơn 1 nên hoán đổi vị trí 4 với 1. Lúc này, 0 trở thành số đầu tiên trong mảng. So sánh 0 lần lượt với các số còn lại. Do không còn số nào nhỏ hơn 0 nữa, nên kết thúc xét số đầu tiên và chuyển sang xét số thứ 2 trong mảng, lúc này là số 4. Lặp lại qúa trình xét ở trên cho tới số cuối cùng trong mảng. Cuối cùng, kết quả chúng ta thu về mảng kết quả là {0, 1, 2, 3, 4}. Với sắp xếp mảng giảm dần trong C, chúng ta cũng sử dụng logic tương tự. Tuy nhiên thay vì tìm số đầu tiên nhỏ hơn số đang xét, thì chúng ta sẽ làm ngược lại là tìm số đầu tiên lớn hơn số đang xét mà thôi. Logic hoán đổi phần tửĐể có thể hoán đổi 2 phần tử như trên, chúng ta cần phải chuẩn bị một vùng tạm thời để chứa một trong 2 phần tử, và hoán đổi với logic temp = X; X = Y; Y = temp; Và để thực hiện được logic hoán đổi 2 số ở trên, chúng ta sẽ sử dụng từ khoá define để tạo một macro dùng để hoán đổi phần tử, mà Kiyoshi đã hướng dẫn trong Đảo ngược mảng trong C như sau: Copy#define SWAP(type,x,y) do&#123;type tmp = x; x = y; y = tmp;&#125;while(0) Sắp xếp mảng trong C bằng hàm tự tạoỨng dụng các kiến thức trên, chúng ta sẽ viết hàm sắp xếp mảng tăng dần trong C và hàm sắp xếp mảng giảm dần trong C như sau: Copy// Tạo hàm sắp xếp mảng tăng dần trong Cvoid asc_order(int array[], int n)&#123; //Tạo vòng lặp để sắp xếp mảng for(int i = 0; i &lt; n - 1; i++)&#123; for(int j = i + 1; j &lt; n; j++)&#123; //Nếu tìm ra số nhỏ hơn đầu tiên thì hoán đổi với số đang xét if(array[i] &gt; array[j]) SWAP(int,array[i],array[j]); &#125; &#125;&#125;// Tạo hàm sắp xếp mảng giảm dần trong Cvoid desc_order(int * array,int n)&#123; //Tạo vòng lặp để sắp xếp mảng for(int i = 0; i &lt; n - 1; i++)&#123; for(int j = i + 1; j &lt; n; j++)&#123; //Nếu tìm ra số lớn hơn đầu tiên thì hoán đổi với số đang xét if(array[i] &lt; array[j]) SWAP(int,array[i],array[j]); &#125; &#125;&#125; Và chúng ta viết chương trình nhập một mảng và sắp xếp phần tử trong mảng C như sau: Copy#include &lt;stdio.h&gt;/*Định nghĩa macro SWAP để hoán đổi phần tử trong mảng chỉ định*/#define SWAP(type,x,y) do&#123;type tmp = x; x = y; y = tmp;&#125;while(0)/*Tạo hàm in phần tử trong mảng*/void show_array(int array[], int length)&#123; for(short i = 0; i &lt; length; i++) printf(&quot;%d &quot;, array[i]); printf(&quot;
