d() +&quot;&#x27;&quot;);//&gt; &#x27; LOVE YOU &#x27;//&gt; &#x27; LOVE YOU&#x27; Ví dụ 3: Xoá dấu tab ở cuối chuỗi JavaScript Copylet str = &quot;	LOVE YOU	&quot;;console.log(&quot;&#x27;&quot;+ str +&quot;&#x27;&quot;);console.log(&quot;&#x27;&quot;+ str.trimEnd() +&quot;&#x27;&quot;);//&gt; &#x27; LOVE YOU &#x27;//&gt; &#x27; LOVE YOU&#x27; Ví dụ 4: Xoá dấu xuống dòng ở cuối chuỗi JavaScript Copylet str = &quot;
